import React from "react";

const BorderBeam = React.forwardRef(
  (
    {
      className = "",
      size = 300,
      duration = 20,
      delay = 0,
      borderWidth = 2,
      colorFrom = "from-transparent",
      colorTo = "to-transparent",
      colorVia = "via-red-500",
    },
    ref
  ) => {
    return (
      <svg
        ref={ref}
        className={`absolute inset-0 pointer-events-none overflow-visible ${className}`}
        width="100%"
        height="100%"
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        style={{
          left: "-2px",
          top: "-2px",
          width: "calc(100% + 4px)",
          height: "calc(100% + 4px)",
        }}
      >
        <defs>
          <linearGradient id={`gradient-${delay}`} x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="rgba(239, 68, 68, 0)" />
            <stop offset="50%" stopColor="rgba(239, 68, 68, 1)" />
            <stop offset="100%" stopColor="rgba(239, 68, 68, 0)" />
          </linearGradient>
          <style>{`
            @keyframes borderBeamAnimate {
              0% {
                stroke-dashoffset: 400;
              }
              100% {
                stroke-dashoffset: 0;
              }
            }
            .border-beam-line {
              stroke-dasharray: 400;
              animation: borderBeamAnimate ${duration}s linear infinite;
              animation-delay: ${delay}s;
            }
          `}</style>
        </defs>
        <rect
          x={borderWidth / 2}
          y={borderWidth / 2}
          width={`calc(100% - ${borderWidth}px)`}
          height={`calc(100% - ${borderWidth}px)`}
          fill="none"
          stroke="url(#gradient-${delay})"
          strokeWidth={borderWidth}
          rx="24"
          ry="24"
          className="border-beam-line"
        />
      </svg>
    );
  }
);

BorderBeam.displayName = "BorderBeam";

export { BorderBeam };
